function dir$dmbv(p){
  this.constructor(p);
  document._dir = p;
}
dir$dmbv.prototype = new DirEvent();
dir$dmbv.prototype.afterInit = function(){
	var p = this._dir;	

	setTimeout(function() {		
		var mota = document.querySelector('input.mo_ta')
		editor_mota = CKEDITOR.replace(mota, {
			customConfig: '/ckeditor/config.js',
			extraAllowedContent: 'span',
			maxLength: 256, 
		});	
		editor_mota.setData(document.querySelector('input.mo_ta').value);
		editor_mota.on('change', function () {
			p.valForm('mo_ta', editor_mota.getData(), true);
		});


		var noidung = document.querySelector('input.noi_dung');		
		editor_noidung = CKEDITOR.replace(noidung, {
			customConfig: '/ckeditor/config.js',
			extraAllowedContent: 'span',
			maxLength: 256, 
		});	
		editor_noidung.setData(document.querySelector('input.noi_dung').value);
		editor_noidung.on('change', function () {
			p.valForm('noi_dung', editor_noidung.getData(), true);
		});	
		setImages('img_ximage1', 'ximage1', p);
	}, 500);		
}
function setImages(id, name, p) {
	$('#' + id).attr("src", p.valForm(name));
}
function updateImage(index) {
	var p = document._dir;

	var input = document.getElementById("fileUpload" + index);
	var selectedFile = input.files[0];
	if (selectedFile) {
		// Cập nhật đường dẫn ảnh trong input ẩn tương ứng
		var path = "/Uploaded/" + selectedFile.name;
		p.valForm('ximage' + index, path, true);
		var formData = new FormData();
		formData.append("file", selectedFile);
		$.showToast("1" + p.msg('uploadCount'));	
		var btn = document.querySelector('button.btn-primary');
		btn.addEventListener("click", function() {
			$.ajax({
				url: '/AppHandler/UploadHandler.ashx',
				type: 'POST',
				data: formData,
				processData: false,
				contentType: false,
				success: function (response) {
					$.showToast(response + p.msg('uploadEmpty'));	
				}
			});
		});
	} else {
		$.showToast(p.msg('uploadUndefined'));	
	}
}
function browseServer(value, src) {
	var p = document._dir;
	var finder = new CKFinder();
	finder.selectActionFunction = function (url) {
		p.valForm(value, url, true);
		document.getElementById(src).src = url;
	};
	finder.popup();
}


